Here is a Python function `eval_expression(expr)` that uses a recursive descent parser to evaluate mathematical expressions. It correctly handles the order of operations (PEMDAS/BODMAS), parentheses, negative numbers, and explicitly raises a `ZeroDivisionError` upon division by zero.

```python
def eval_expression(expr):
    # Remove all whitespace from the expression
    expr = expr.replace(" ", "")
    if not expr:
        raise ValueError("Empty expression")

    def parse_expression(s, index):
        value, index = parse_term(s, index)
        while index < len(s):
            op = s[index]
            if op in "+-":
                index += 1
                next_value, index = parse_term(s, index)
                if op == "+":
                    value += next_value
                else:
                    value -= next_value
            else:
                break
        return value, index

    def parse_term(s, index):
        value, index = parse_factor(s, index)
        while index < len(s):
            op = s[index]
            if op in "*/":
                index += 1
                next_value, index = parse_factor(s, index)
                if op == "*":
                    value *= next_value
                else:
                    if next_value == 0:
                        raise ZeroDivisionError("division by zero")
                    value /= next_value
            else:
                break
        return value, index

    def parse_factor(s, index):
        if index >= len(s):
            raise ValueError("Unexpected end of expression")

        # Handle unary operators (negative/positive numbers)
        sign = 1
        if s[index] == "-":
            sign = -1
            index += 1
        elif s[index] == "+":
            index += 1

        if index >= len(s):
            raise ValueError("Unexpected end of expression")

        # Handle parentheses
        if s[index] == "(":
            index += 1  # skip '('
            value, index = parse_expression(s, index)
            if index >= len(s) or s[index] != ")":
                raise ValueError("Mismatched parentheses")
            index += 1  # skip ')'
            return sign * value, index

        # Handle numbers (integers and floats)
        start = index
        while index < len(s) and (s[index].isdigit() or s[index] == "."):
            index += 1

        if start == index:
            raise ValueError(f"Unexpected character at index {index}")

        number_str = s[start:index]
        try:
            # Parse as float if it contains a decimal point, else int
            if "." in number_str:
                value = float(number_str)
            else:
                value = int(number_str)
        except ValueError:
            raise ValueError(f"Invalid number format: {number_str}")

        return sign * value, index

    # Start parsing from the beginning of the string
    result, idx = parse_expression(expr, 0)

    # Ensure the entire string was consumed
    if idx != len(expr):
        raise ValueError(f"Unexpected trailing characters at index {idx}")

    return result


# --- Example Usage ---
if __name__ == "__main__":
    print(eval_expression("3 + 4 * (2 - 1)"))  # Output: 7
    print(eval_expression("-5 + 3 * (-2 + 4)"))  # Output: 1
    print(eval_expression("10 / (5 - 5)"))  # Raises ZeroDivisionError
```

### Features:
1. **Order of Operations**: Follows standard precedence (parentheses first, then multiplication/division, then addition/subtraction).
2. **Parentheses Support**: Handles nested parentheses correctly.
3. **Negative Numbers**: Supports unary minus signs (e.g., `-5`, `(-2 + 4)`).
4. **Division by Zero**: Explicitly checks for `0` divisors and raises Python's built-In `ZeroDivisionError`.
5. **Security**: Unlike Python's built-in `eval()`, this custom parser only evaluates arithmetic and is completely safe from arbitrary code execution.

